DROP TABLE refuse_fault_candidates;
DROP TRIGGER fault_candidates_fill;
DROP TRIGGER fault_candidates_refill;
DROP TRIGGER fault_candidates_bad;
ALTER TABLE fault_candidates DROP COLUMN body;
CREATE TRIGGER fault_candidates_rest_insert BEFORE INSERT ON fault_candidates WHEN json_type(NEW.rest, '$.depends') IS NOT NULL OR json_type(NEW.rest, '$.done_state') IS NOT NULL OR json_type(NEW.rest, '$.faults') IS NOT NULL OR json_type(NEW.rest, '$.id') IS NOT NULL OR json_type(NEW.rest, '$.item') IS NOT NULL OR json_type(NEW.rest, '$.phase') IS NOT NULL OR json_type(NEW.rest, '$.repo') IS NOT NULL OR json_type(NEW.rest, '$.status') IS NOT NULL BEGIN SELECT RAISE(ABORT, 'fault_candidates.rest holds a field that has a column'); END;
CREATE TRIGGER fault_candidates_rest_update BEFORE UPDATE OF rest ON fault_candidates WHEN json_type(NEW.rest, '$.depends') IS NOT NULL OR json_type(NEW.rest, '$.done_state') IS NOT NULL OR json_type(NEW.rest, '$.faults') IS NOT NULL OR json_type(NEW.rest, '$.id') IS NOT NULL OR json_type(NEW.rest, '$.item') IS NOT NULL OR json_type(NEW.rest, '$.phase') IS NOT NULL OR json_type(NEW.rest, '$.repo') IS NOT NULL OR json_type(NEW.rest, '$.status') IS NOT NULL BEGIN SELECT RAISE(ABORT, 'fault_candidates.rest holds a field that has a column'); END;
DROP TRIGGER selection_misses_gone;
CREATE TABLE misses(n INTEGER PRIMARY KEY, queue TEXT NOT NULL, day TEXT, at REAL NOT NULL, run TEXT, item TEXT, kind TEXT, sha TEXT, source TEXT, script TEXT, step TEXT, test TEXT, failed INTEGER, missed INTEGER, selected INTEGER, steps INTEGER, steps_missed INTEGER, miss INTEGER CHECK (miss IN (0, 1)), pre_ran INTEGER CHECK (pre_ran IN (0, 1)), rest TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(rest))) STRICT;
INSERT INTO misses(n, queue, day, at, run, item, kind, sha, source, script, step, test, failed, missed, selected, steps, steps_missed, miss, pre_ran, rest) SELECT n, queue, day, at, run, item, kind, sha, source, script, step, test, failed, missed, selected, steps, steps_missed, miss, pre_ran, rest FROM selection_misses;
DROP TABLE selection_misses;
ALTER TABLE misses RENAME TO selection_misses;
CREATE UNIQUE INDEX selection_misses_once ON selection_misses(queue, coalesce(day, ''), coalesce(run, ''), coalesce(kind, ''), coalesce(item, ''), coalesce(sha, ''), coalesce(source, ''), coalesce(step, ''), coalesce(test, ''));
CREATE INDEX selection_misses_queue ON selection_misses(queue, n);
CREATE TRIGGER selection_misses_gone AFTER DELETE ON selection_misses BEGIN
  DELETE FROM miss_files WHERE n = OLD.n;
END;
CREATE TRIGGER selection_misses_rest_insert BEFORE INSERT ON selection_misses WHEN json_type(NEW.rest, '$.changed') IS NOT NULL OR json_type(NEW.rest, '$.day') IS NOT NULL OR json_type(NEW.rest, '$.failed') IS NOT NULL OR json_type(NEW.rest, '$.item') IS NOT NULL OR json_type(NEW.rest, '$.kind') IS NOT NULL OR json_type(NEW.rest, '$.miss') IS NOT NULL OR json_type(NEW.rest, '$.missed') IS NOT NULL OR json_type(NEW.rest, '$.pre_ran') IS NOT NULL OR json_type(NEW.rest, '$.script') IS NOT NULL OR json_type(NEW.rest, '$.selected') IS NOT NULL OR json_type(NEW.rest, '$.sha') IS NOT NULL OR json_type(NEW.rest, '$.source') IS NOT NULL OR json_type(NEW.rest, '$.step') IS NOT NULL OR json_type(NEW.rest, '$.steps') IS NOT NULL OR json_type(NEW.rest, '$.steps_missed') IS NOT NULL OR json_type(NEW.rest, '$.test') IS NOT NULL BEGIN SELECT RAISE(ABORT, 'selection_misses.rest holds a field that has a column'); END;
CREATE TRIGGER selection_misses_rest_update BEFORE UPDATE OF rest ON selection_misses WHEN json_type(NEW.rest, '$.changed') IS NOT NULL OR json_type(NEW.rest, '$.day') IS NOT NULL OR json_type(NEW.rest, '$.failed') IS NOT NULL OR json_type(NEW.rest, '$.item') IS NOT NULL OR json_type(NEW.rest, '$.kind') IS NOT NULL OR json_type(NEW.rest, '$.miss') IS NOT NULL OR json_type(NEW.rest, '$.missed') IS NOT NULL OR json_type(NEW.rest, '$.pre_ran') IS NOT NULL OR json_type(NEW.rest, '$.script') IS NOT NULL OR json_type(NEW.rest, '$.selected') IS NOT NULL OR json_type(NEW.rest, '$.sha') IS NOT NULL OR json_type(NEW.rest, '$.source') IS NOT NULL OR json_type(NEW.rest, '$.step') IS NOT NULL OR json_type(NEW.rest, '$.steps') IS NOT NULL OR json_type(NEW.rest, '$.steps_missed') IS NOT NULL OR json_type(NEW.rest, '$.test') IS NOT NULL BEGIN SELECT RAISE(ABORT, 'selection_misses.rest holds a field that has a column'); END;
ALTER TABLE commit_gated DROP COLUMN body;
